from questions._util import IX, q

URL_CGROUP = "https://labs.iximiuz.com/skill-paths/get-started-with-cgroups"
URL_IPTABLES = "https://labs.iximiuz.com/challenges/linux-preserve-iptables-rules"

QUESTIONS = [
    q("linux-processes", "medium", "A service is up but slow, and load average is high while CPU idle stays high. What does that usually mean?", "Work is stuck waiting on I/O or uninterruptible sleep, not burning CPU.", "The host is out of process IDs.", "The OOM killer is about to fire.", "Every CPU core is in userspace.", "Load average counts tasks that are running or waiting on I/O. High load with idle CPU points at waiting, often disk or a stuck filesystem."),
    q("linux-processes", "medium", "You need the parent of a stuck process and what it is waiting on. Which pair of facts is the useful one?", "PPID from the process list, and the wchan or stack in /proc.", "Only the process name from ps, which includes the wait channel.", "The executable inode, which stores the parent.", "nice, which is the parent pid.", "ps shows PPID. /proc/<pid>/wchan or the stack shows the kernel wait. The name and niceness do not tell you who spawned it or why it is stuck."),
    q("linux-processes", "hard", "A zombie is accumulating. What actually clears it?", "The parent calls wait. Killing the zombie itself does nothing, because it is already dead.", "Restarting the process with the same PID.", "Dropping caches.", "Raising nofile.", "A zombie is an exited child whose parent has not collected the status. Reparent it to init by killing a stuck parent if that parent will never wait."),
    q("linux-processes", "easy", "What is a reasonable first check when a host feels busy?", "uptime, the runnable and blocked counts, and which processes are in D or R.", "Immediately reboot so the load average resets.", "Delete /var/log.", "Disable swap before looking at anything else.", "Characterize the host before changing it: load, CPU versus I/O wait, and the process states."),
    q("linux-signals", "medium", "A process ignores SIGTERM and you need it gone. What is the honest next step?", "SIGKILL, knowing it cannot be caught and will not run cleanup.", "SIGSTOP, which terminates after the next syscall.", "SIGHUP, which the kernel treats as an unblockable kill.", "SIGCHLD, which reaps and deletes the process.", "SIGTERM can be handled. SIGKILL cannot. Use it when a process will not exit, and expect no graceful shutdown."),
    q("linux-signals", "medium", "You want a daemon to reopen its log files after logrotate. Which signal is the usual convention?", "SIGHUP", "SIGPIPE", "SIGURG", "SIGWINCH", "Many daemons treat SIGHUP as 'reload configuration and reopen files'. logrotate often sends it for that reason. It is a convention, not a kernel rule."),
    q("linux-signals", "hard", "A write to a closed socket kills the client with no error handling. Which signal is that, and why did it happen?", "SIGPIPE. The default action is to terminate the writer.", "SIGALRM. Sockets always arm a one-second timer.", "SIGIO. It is fatal unless the process is root.", "SIGXFSZ. It fires when a TCP window closes.", "Writing to a pipe or socket whose read end is gone raises SIGPIPE. Programs that want EPIPE instead ignore or mask it."),
    q("linux-signals", "easy", "What does SIGSTOP do that SIGTSTP does not?", "SIGSTOP cannot be caught or ignored. SIGTSTP is the terminal's suspend key and can be handled.", "SIGSTOP reboots the session. SIGTSTP only logs.", "They are the same signal number.", "SIGSTOP is ignored by PID 1 only, and SIGTSTP is always fatal.", "SIGSTOP is unblockable. SIGTSTP is what Ctrl-Z sends, and a process may catch it."),
    q("linux-systemd", "medium", "A unit is enabled but the machine just booted and the service is inactive. What does enabled actually mean?", "It will be started on boot according to its install rules. It does not mean it is running now.", "The process is running and will respawn forever.", "The unit file was deleted from /etc.", "systemctl status will always show active (running).", "enable installs the boot symlink. start is what runs it now. A failed boot can leave an enabled unit inactive."),
    q("linux-systemd", "medium", "A service keeps restarting and you want the reason, not another restart. Where do you look first?", "journalctl -u for that unit, then the exit status in systemctl status.", "Only dmesg, because user services never reach the journal.", "/etc/passwd.", "The crontab of root, which systemd always mirrors.", "The journal has stdout, stderr, and the manager's result code. status shows the last exit and whether Restart= is looping it."),
    q("linux-systemd", "hard", "You need a one-off command limited to 512M of memory without writing a unit file. What fits?", "systemd-run with a transient unit and MemoryMax.", "nice -n 512.", "ulimit in /etc/fstab.", "sysctl vm.max_map_count.", "systemd-run creates a transient scope or service. MemoryMax on cgroup v2 is the cap. nice only changes scheduling priority."),
    q("linux-systemd", "medium", "RestrictNetworkInterfaces= on a service does what?", "It limits which host interfaces that service's processes may use.", "It changes the default route for the whole host.", "It installs an nftables table named after the unit.", "It binds the service to 127.0.0.1 only.", "The setting is a per-service network restriction in systemd, useful when a daemon should speak on one NIC of a dual-homed host.", "iximiuz", "https://labs.iximiuz.com/challenges/networking-block-unexpected-access-on-dual-homed-server"),
    q("linux-users", "medium", "A user can log in with a key but sudo fails with 'not in the sudoers file'. What is missing?", "A sudoers rule or group membership such as sudo or wheel. The account existing is not enough.", "A password hash of '*'. That grants sudo.", "Ownership of /bin/su by that user.", "A world-writable /etc/shadow.", "sudo reads sudoers. Group membership is the usual path. Login and privilege escalation are separate."),
    q("linux-users", "easy", "What does a shell of /usr/sbin/nologin do?", "It refuses interactive login. The account can still own files and run as a service user.", "It deletes the home directory on each attempt.", "It grants root for cron only.", "It disables the account's UID.", "nologin is a shell that exits with a refusal. Service accounts use it so nobody gets a prompt."),
    q("linux-users", "medium", "You must let a deploy user restart one service and nothing else. Where does that belong?", "A sudoers rule limited to that systemctl command, not membership in a group that can run all of sudo.", "A copy of root's authorized_keys.", "chmod 4755 on systemctl.", "Adding the user to the disk group.", "Least privilege for sudo is a command-scoped rule. The disk group and a setuid systemctl are far broader than a restart."),
    q("linux-users", "hard", "Why is the docker group on a host effectively root?", "Anyone who can talk to the Docker socket can start a privileged container and rewrite the host.", "The group is hard-coded as UID 0.", "Docker drops all capabilities for members of that group.", "The kernel grants CAP_SYS_ADMIN to supplementary groups.", "The socket is usually root:docker mode 660. Socket access is full daemon access, and the daemon runs as root unless you are on rootless Docker.", "iximiuz", "https://labs.iximiuz.com/tutorials/docker-security-introduction-a859718d"),
    q("linux-permissions", "medium", "A file is mode 644, owned by root:app, and the app user is in group app. Can the app user write it?", "No. 644 is owner read/write, group read, others read. Group write would be 664.", "Yes, because group membership overrides the mode.", "Yes, because the directory is what matters and the file mode is ignored.", "Only if the process is not in a container.", "The middle digit is the group. 4 is read. Write needs 6 or 2 in that position, or an ACL."),
    q("linux-permissions", "medium", "A script is executable and the directory is 755, but the service user still cannot run it. The script's interpreter line points at a binary the user cannot execute. What is the failure?", "The kernel can read the script but exec of the interpreter fails.", "The directory sticky bit blocks interpreters.", "Executable scripts ignore the shebang when the file is not owned by root.", "755 on a directory removes the execute bit from files inside it.", "Running a script means executing the interpreter with the script as input. The interpreter itself must be executable by that user."),
    q("linux-permissions", "hard", "Setuid on a shell script is a poor way to grant privilege. Why do operators avoid it?", "The kernel historically ignores the setuid bit on scripts, and a setuid binary that calls a script is easy to trick via PATH and environment.", "Setuid only works on directories.", "The bit forces the process into the caller's group and drops root.", "Scripts cannot be executable and setuid at the same time because of the shebang length.", "Use a small, careful setuid helper or capabilities, not a setuid shell script. The environment and interpreter are the attack."),
    q("linux-permissions", "easy", "What does the execute bit on a directory mean?", "You may traverse it and access entries by name. Listing still needs the read bit.", "You may delete every file inside, even ones you do not own.", "The directory's files become executable.", "New files inherit that execute bit.", "Directory execute is search/traverse. Read is list. Write plus execute is create and remove names."),
    q("linux-files", "medium", "rm of a file that is still open by a process frees the disk space immediately. True or false, and why?", "False. The directory entry is gone, but the inode stays until the last file descriptor closes.", "True. open file descriptors are paths, and rm deletes those too.", "True, but only on ext4.", "False, because rm never unlinks a busy file and returns EBUSY always.", "Unlink removes the name. Space returns when the link count and the open count both hit zero. A deleted log can still fill the disk."),
    q("linux-files", "medium", "A symlink and a hard link differ how?", "A symlink is a path stored in a new inode. A hard link is another name for the same inode, and it cannot cross filesystems.", "A hard link can point at a directory on another disk. A symlink cannot point at a file.", "They are the same structure with a different permission bit.", "A symlink shares the inode number and a hard link does not.", "Hard links are extra directory entries for one inode, same filesystem only. Symlinks are their own inode holding a target path."),
    q("linux-files", "hard", "You copy a tree with cp -a and the application still writes to the old path. What did you fail to move?", "The running process has the old inode open. Copying names does not retarget open descriptors.", "cp -a follows no symlinks and therefore copies nothing.", "The new tree has no inodes until reboot.", "cp never preserves directory entries.", "Replacing a binary or a log on disk does not change a process that already mapped or opened the old inode. Restart the process."),
    q("linux-files", "easy", "What does df show that du of one directory does not?", "df is the filesystem, including other directories, deleted-but-open files, and reserved blocks. du is a tree walk.", "df counts inodes of a single folder. du counts free space for the whole disk.", "They always match, to the byte.", "df ignores the filesystem the directory is mounted on.", "If du looks small and df says the disk is full, suspect another mount, a deleted open file, or reserved root space."),
    q("linux-disks", "medium", "lsblk shows a disk, but it is not in df. What is the usual gap?", "The disk or partition exists and is not mounted. df only lists mounted filesystems.", "df hides anything larger than 2G.", "lsblk lists network mounts only.", "The kernel has not created the device node yet if lsblk can see it.", "Block devices can be partitioned and formatted and still unused. Mount is a separate step."),
    q("linux-disks", "medium", "You formatted a new partition and rebooted. The filesystem is gone from the tree. Why?", "Nothing in fstab or a systemd mount unit mounts it. Formatting does not persist the mount.", "mkfs stores the mount point inside the superblock and the superblock was not labeled.", "Reboot always wipes filesystems that are not ext4.", "The partition table cannot survive a reboot.", "Persistence is fstab, a generator, or a mount unit. The filesystem itself survives. The attachment does not, unless you record it."),
    q("linux-disks", "hard", "An ext4 filesystem is full, df shows free space, and root can write but the app cannot. What is a classic cause?", "Reserved blocks for root, typically 5 percent, so a non-root user hits ENOSPC first.", "The journal is stored on a different disk that only root can see.", "ext4 hides free space from every user except UID 1, which is not root.", "df counts inodes and the app is looking at blocks, so they can never agree.", "tune2fs shows the reserved count. Lower it if this is a data disk and root does not need the reserve. Also check inodes separately with df -i."),
    q("linux-disks", "easy", "What does df -i tell you that df does not?", "Whether you are out of inodes even though blocks remain.", "The SMART health of the physical disk.", "Which process holds a deleted file.", "The LVM thin pool metadata size.", "A filesystem can fail creates with 'no space' because inode tables are exhausted. df without -i will still show free blocks."),
    q("linux-mounts", "medium", "A bind mount of a directory into a chroot is useful because:", "It attaches an existing tree at a second path without copying bytes.", "It snapshots the directory into a new filesystem.", "It changes the directory's owner to root.", "It encrypts the tree for the duration of the mount.", "mount --bind is another view of the same inode tree. It is how containers and chroots expose a host path."),
    q("linux-mounts", "medium", "findmnt is a better first tool than reading /etc/fstab when a path looks wrong. Why?", "findmnt shows what is mounted now, including bind mounts and propagation. fstab is only the requested configuration.", "fstab is rewritten every minute to match the live table, so findmnt is historical.", "findmnt edits fstab safely.", "The kernel ignores fstab after the first week of uptime.", "Live state and intended state diverge. Look at the mount table before editing fstab."),
    q("linux-mounts", "hard", "A container cannot see a file you just wrote on the host path you thought was mounted. What should you check?", "The mount is on a different path, a different mount namespace, or a file hidden by a later mount on top of the directory.", "Host writes are invisible to containers until the page cache is dropped.", "Bind mounts only flow from container to host.", "The file must be mode 777 or the mount refuses to show it.", "Mount namespaces and stacked mounts hide files. Confirm the namespace and the exact target with findmnt inside the container."),
    q("linux-mounts", "easy", "What does the noexec mount option stop?", "Running binaries from that filesystem. It does not stop reading them.", "All writes.", "Root logging in.", "Creating symlinks.", "noexec is a control on a data volume so a dropped binary cannot be executed from it. The interpreter-on-the-host trick can still read a script."),
    q("linux-packages", "medium", "apt says a package is not installed, but the binary is on PATH. What is a plausible reason?", "It was copied, built from source, or installed with a different package manager. The distro database is not the whole machine.", "apt only indexes packages newer than the running kernel.", "PATH never includes files dpkg knows about.", "Binaries unregister themselves after the first run.", "which and dpkg -S tell you if the distro owns the file. Homebrew, a tarball, or a vendored path will not show up as an apt package."),
    q("linux-packages", "easy", "What is the point of apt update before apt install on a fresh shell?", "The local package index may be older than the repository. update refreshes the index. It does not upgrade installed packages.", "update upgrades every installed package and reboots.", "update only works offline.", "install always refreshes the index first, so update is a no-op.", "update fetches metadata. upgrade is the thing that changes installed versions. install uses whatever index you have."),
    q("linux-packages", "medium", "A package upgrade replaced a config file you had edited. Debian asked you, and you kept the old one. What should you still do?", "Read the dpkg .ucf or the 'new' file it saved, and merge the maintainer's changes. Keeping yours can leave a daemon unable to start.", "Delete /etc. The package will restore defaults on the next boot automatically.", "Nothing. Kept files are guaranteed compatible.", "Reinstall the kernel.", "Config prompts exist because both sides may be right. A kept file that misses a new required key is a common outage after upgrade."),
    q("linux-packages", "hard", "Why pin a package instead of holding the whole upgrade forever?", "A pin freezes one package you know is risky. Holding all upgrades piles up security fixes you meant to take.", "Pins delete the package from the repository.", "A pin upgrades the package daily.", "Holding upgrades still installs security updates by default.", "Pin or hold the exception. Take the rest. An unpatched host is not a strategy."),
    q("linux-shell", "medium", "A cron job works when you paste it into the terminal and fails at night. What is the usual difference?", "Cron has a minimal environment: PATH, cwd, and missing variables. Your shell startup files did not run.", "Cron runs as root even when the crontab is a user's.", "The shell in cron cannot run pipes.", "Nightly jobs always see a read-only filesystem.", "Set PATH inside the crontab or use absolute paths. Do not assume .bashrc."),
    q("linux-shell", "medium", "set -euo pipefail at the top of a bash script is there to:", "Exit on a failed command, an unset variable, or a failed command in a pipeline.", "Disable all errors so the script always returns 0.", "Run the script under dash.", "Turn every variable into an environment variable.", "Without pipefail, a pipeline's status is the last command. A failing curl | tee can look successful. -u catches typos in variable names."),
    q("linux-shell", "hard", "A pipeline's overall status is needed, and the script uses bash. What reports a failure in the middle of the pipe?", "set -o pipefail, then look at $?.", "set -x alone.", "The PIPESTATUS array does not exist in bash.", "echo $? always prints the first command, even without pipefail.", "pipefail makes the pipeline fail if any stage fails. PIPESTATUS still has the per-stage codes."),
    q("linux-shell", "easy", "Why quote \"$var\" when the variable holds a path?", "Unquoted expansion splits on whitespace and globs. A path with a space becomes multiple arguments.", "Quotes disable the variable.", "The kernel rejects quoted paths.", "Quoting converts the path to a URL.", "Quote expansions unless you mean to split them."),
    q("linux-text", "medium", "You need the second field of a colon-separated file. What is the direct tool?", "cut -d: -f2, or awk -F: '{print $2}'.", "tr, which selects fields.", "head -2, which prints field 2 of every line.", "uniq -f2.", "cut and awk both do fields. head is lines. uniq collapses duplicates."),
    q("linux-text", "medium", "A log line is huge and you want a count of each status code. What is the usual shape?", "Extract the field, sort, then uniq -c.", "wc -l on the raw file, which groups by field.", "tail -f, which prints counts.", "paste, which histograms.", "sort | uniq -c is the classic frequency count. awk can do it in one pass."),
    q("linux-text", "hard", "grep -r on a directory that contains a binary and a huge journal is painful. What narrows it?", "grep -r --include or a path, and -I or -a only when you mean to treat binary as text.", "grep -v, which skips directories.", "grep always skips files over 1K.", "Use ls | grep, which searches file contents.", "Limit the file set. Recursive grep of /var is how people melt a disk."),
    q("linux-text", "easy", "What is jq for, next to grep, on an operator workstation?", "Selecting and reshaping JSON. grep only sees the raw text.", "Compiling Go.", "Rotating logs.", "Editing ext4 inodes.", "API and journal output is JSON. jq is the field tool. grep still finds a string when you do not know the shape."),
    q("linux-ssh", "medium", "You want a shell on a host that is only reachable from a bastion, without copying your key onto the bastion. What is the mechanism?", "ProxyJump or a ProxyCommand. Your key stays on the laptop and the bastion only forwards the TCP connection.", "ssh-copy-id to the bastion, then agent forwarding of every key by default.", "A local -L forward of port 22 to yourself.", "SSH cannot hop.", "ProxyJump (-J) is the straightforward form. The bastion does not need your private key."),
    q("linux-ssh", "medium", "Password authentication is on, root login is on, and the host is on the internet. What is the first hardening that removes the common brute force?", "Disable password auth and root login, and use keys.", "Move SSH to port 2222 and leave passwords on. That is sufficient.", "Install a second sshd on port 22 with an empty password.", "Turn off UsePAM and leave PasswordAuthentication yes.", "Keys plus no root password login removes the attack that scans port 22. A new port is obscurity, not the control.", "iximiuz", "https://labs.iximiuz.com/tutorials/2fa-pkey-auth-linux-ssh-b1dcdb9a"),
    q("linux-ssh", "hard", "Agent forwarding to a shared bastion is risky because:", "A process on the bastion can use your agent to authenticate as you while the session is open.", "The agent copies your private key into authorized_keys on the bastion permanently.", "Forwarding disables the key.", "The bastion's root password is sent to your laptop.", "Forward the agent only to hosts you trust, for as long as you need it. The socket on the far side is usable by anyone who can reach it as you."),
    q("linux-ssh", "easy", "Where does an OpenSSH client look for your private key by default?", "Under ~/.ssh, for names such as id_ed25519, unless IdentityFile or an agent overrides it.", "In /etc/shadow.", "In the remote host's authorized_keys. That file holds the private key.", "In the shell history.", "The private key stays on the client. authorized_keys holds public keys."),
    q("linux-logs", "medium", "journalctl -u nginx --since '1 hour ago' is empty, but the site is serving. What is a likely split?", "Nginx is logging to files in /var/log, and the journal only has the unit's stdout.", "journalctl cannot see a service that is running.", "Nginx disables all logs when the journal is empty.", "The since filter only matches kernel messages.", "Daemons that log to files will not appear in the journal unless stderr is also captured. Check both."),
    q("linux-logs", "easy", "A disk fills with logs overnight. What stops the repeat without deleting the only copy you might need?", "logrotate with size or time rules, and a look at which unit is suddenly verbose.", "chmod 000 /var/log so nothing can write.", "Turn off the journal permanently.", "Delete /var.", "Rotation plus finding the noisy source. A one-time delete fills again."),
    q("linux-logs", "medium", "You need lines from a structured journal for one request id. What helps?", "journalctl -o json and a filter, or grep on the message if the id is in the text.", "dmesg -i, which indexes request ids.", "lastlog, which stores HTTP requests.", "utmp.", "The journal can emit JSON. Request ids live in the message or in a field the application added. utmp is logins, not HTTP."),
    q("linux-logs", "hard", "Persistent journal storage is off and you rebooted. What did you lose?", "The previous boot's journal. A volatile journal lives in /run and dies with the machine.", "Only kernel logs. User logs are always on disk.", "Nothing. journald always writes /var/log/journal even when Storage=volatile.", "The package database.", "Set Storage=persistent if you need logs after a crash. Otherwise the evidence is gone when you reboot to recover."),
    q("linux-cgroups", "medium", "Kubernetes sets a memory limit on a container. What happens when the process allocates past it?", "The cgroup OOM killer stops a process in that cgroup. The node does not have to be out of memory.", "The kernel ignores container limits and only OOMs the whole host.", "The container is paused until the next day.", "The limit only affects CPU, so memory allocations always succeed.", "memory.max on cgroup v2 is a hard cap for that subtree. The host can have free memory and the container still dies."),
    q("linux-cgroups", "medium", "CPU requests in Kubernetes and a cpu.max limit are different. Which statement is right?", "The request steers scheduling. The limit is the cgroup throttle.", "They are the same number written to the same file.", "The request throttles the container. The limit only changes the nice value.", "Neither touches cgroups. The kubelet simulates them.", "Requests are a scheduling claim. Limits become cgroup bandwidth. A pod can be throttled while the node looks idle.", "iximiuz", URL_CGROUP),
    q("linux-cgroups", "hard", "Where do you look on a cgroup v2 host to see a running service's memory cap?", "Under /sys/fs/cgroup, in the service's cgroup, at memory.max.", "In /proc/cpuinfo.", "In /etc/cgroup.conf only. The sysfs tree is a cache.", "nice -n.", "cgroup v2 is a single hierarchy. The controller files in the cgroup directory are the live settings."),
    q("linux-cgroups", "easy", "What problem do cgroups solve that nice does not?", "They account and cap a group of processes for memory, CPU, and IO. nice is only a CPU scheduling hint.", "They replace the need for a kernel.", "They encrypt process memory.", "They assign IP addresses.", "nice will not stop a leak from taking the machine down. A memory cgroup will."),
    q("linux-namespaces", "medium", "A container is a process you can see from the host. What makes it look like its own machine?", "Namespaces (pid, mount, network, user, uts, ipc) plus cgroups. Not a separate kernel.", "A second kernel loaded into the process.", "A virtual machine by definition. Containers cannot be plain processes.", "Only a chroot. Namespaces are optional marketing.", "ps on the host shows the container process. Inside, namespaces hide the rest of the host. The kernel is shared, which is why a breakout matters.", "iximiuz", "https://labs.iximiuz.com/tutorials/docker-security-introduction-a859718d"),
    q("linux-namespaces", "medium", "The container has its own eth0 and you cannot see it in the host's ip addr. Why?", "It is in a network namespace. The host's default namespace has the veth peer, not the container's eth0.", "ip addr hides interfaces whose names are eth0.", "Network namespaces share one interface table.", "The interface is a file in /etc.", "ip netns or nsenter -t <pid> -n ip addr shows the container's interfaces. The host sees the other end of the veth."),
    q("linux-namespaces", "hard", "A user namespace lets a process be root inside and nobody special outside. Why does that matter for rootless containers?", "UID 0 in the container is mapped to an unprivileged UID on the host, so a breakout is not automatically host root.", "User namespaces disable the mapping and always use UID 0 on the host.", "They only work for UDP.", "They replace seccomp.", "Rootless Docker uses that map. Inside, id says root. On the host, ps shows the ordinary user.", "iximiuz", "https://labs.iximiuz.com/tutorials/docker-security-introduction-a859718d"),
    q("linux-namespaces", "easy", "What does a PID namespace change?", "PID 1 and the set of visible processes. It does not give the process a new kernel.", "The CPU architecture.", "The disk encryption key.", "The hostname only. That is the UTS namespace.", "UTS is hostname. PID is the process id space. A container's init is PID 1 inside its namespace."),
    q("linux-netfilter", "medium", "You added an iptables rule and rebooted. The port is exposed again. Why?", "iptables rules are runtime state unless a package or unit restores them.", "iptables writes /etc/iptables automatically on every insert.", "Reboot flushes only rules that use the word DROP.", "nftables and iptables persist themselves in the kernel image.", "Install a persistence path, or put the rules in a unit that runs at boot. The insert you typed was only in memory.", "iximiuz", URL_IPTABLES),
    q("linux-netfilter", "hard", "A service listens on one IP of a dual-homed host and is still reachable on that IP via the other NIC. Binding tighter did not help. Why?", "Linux is a weak end host. It accepts packets for any local address no matter which interface they arrive on. Filter by ingress interface.", "The weak host model drops those packets, so this cannot happen.", "ss -ltnp is wrong whenever a host has two NICs.", "Only a router can have two interfaces.", "Change the firewall to drop that destination when it arrives on the wrong NIC, or restrict the service's interfaces. The listen address is not the control.", "iximiuz", "https://labs.iximiuz.com/challenges/networking-block-unexpected-access-on-dual-homed-server"),
    q("linux-netfilter", "medium", "nft and iptables on a modern distro often program the same kernel tables. What should you avoid?", "Editing both as if they were independent copies of the ruleset.", "Using nft at all.", "Matching on dport.", "Persisting either of them.", "One ruleset, one tool path. Two front ends stepping on the same hooks produce surprises."),
    q("linux-netfilter", "easy", "What does a default-drop input policy require you to remember?", "Allow the traffic you still need, including established connections and management access, before you disconnect yourself.", "Drop means log. Traffic still flows.", "Input rules do not apply to the local machine.", "A default drop also deletes routes.", "Lockouts happen when the allow for SSH is below the policy change and you are not on a console."),
    q("linux-troubleshooting", "medium", "A disk is full and du of the big directories does not add up to df. What is the classic missing piece?", "A deleted file still held open by a process. lsof +L1 or the fd links in /proc show it.", "df counts RAM.", "du skips directories named log.", "The filesystem is always lying about ext4.", "Restart the process that holds the deleted file, or truncate it via the /proc fd, after you know what it is."),
    q("linux-troubleshooting", "medium", "SSH died after a firewall change and you have no console. What would have prevented the lockout?", "A second path, a timed revert, or applying the rules in a way that rolls back if you do not confirm.", "Setting the input policy to drop as the first command.", "Disabling sshd before changing rules.", "There is no way to test firewall rules.", "Operators use at, systemd-run timers, or a confirm script so a bad ruleset reverts."),
    q("linux-troubleshooting", "hard", "The host answers ping and nothing else. Web and SSH hang. What is a useful split?", "Ping is ICMP. SSH and HTTP are TCP. A filter or a full connection table can break one and not the other.", "Ping uses TCP port 7, so it proves every TCP port is open.", "If ping works, the firewall cannot be involved.", "SSH and ping share a port.", "Test the layer you care about. ICMP success does not prove TCP/22 or a path MTU that can carry a handshake."),
    q("linux-troubleshooting", "easy", "Before you change a broken host, what do you record?", "What is true now: who is logged in, disk, memory, the failing unit, and the last change.", "Only the hostname.", "A reboot, so the record is clean.", "The output of rm -rf /tmp.", "You cannot tell a fix from a coincidence if you did not look first."),
]
